#!/usr/bin/env node
// TYRE-21. Asserts that nothing in a lockfile is younger than the configured
// release-age window.
//
// Why this exists when web/.npmrc already sets min-release-age: npm only
// applies that during *resolution*. `npm ci` installs from the lockfile
// verbatim and never re-resolves, so a lockfile regenerated by anything that
// does not honour the setting — Renovate's lockFileMaintenance, a contributor
// on npm < 11.10.0, a hand-edit — sails through CI untouched. This checks the
// artefact rather than the tool that produced it, which is the only check that
// holds regardless of who produced it.
//
// The window and the exemptions are read from the .npmrc itself so there is
// exactly one source of truth: npm and this gate cannot disagree about policy.

import { readFileSync } from 'node:fs';
import { argv, exit } from 'node:process';

const DAY = 86_400_000;
const CONCURRENCY = 8;

function arg(flag, fallback) {
  const i = argv.indexOf(flag);
  return i !== -1 && argv[i + 1] ? argv[i + 1] : fallback;
}

const lockPath = arg('--lockfile', 'web/package-lock.json');
const npmrcPath = arg('--npmrc', 'web/.npmrc');

// npm's own config parser accepts a key repeated across lines and comma
// separated values on one; mirror both so this agrees with npm on any .npmrc
// a person actually writes.
function readNpmrc(path) {
  const out = new Map();
  let text;
  try {
    text = readFileSync(path, 'utf8');
  } catch {
    return out;
  }
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || line.startsWith('#') || line.startsWith(';')) continue;
    const eq = line.indexOf('=');
    if (eq === -1) continue;
    const key = line.slice(0, eq).trim();
    const value = line.slice(eq + 1).trim();
    const prev = out.get(key) ?? [];
    out.set(key, prev.concat(value.split(',').map((v) => v.trim()).filter(Boolean)));
  }
  return out;
}

const npmrc = readNpmrc(npmrcPath);
const windowDays = Number(npmrc.get('min-release-age')?.[0]);
if (!Number.isFinite(windowDays) || windowDays <= 0) {
  console.error(`::error::no usable min-release-age in ${npmrcPath} — the gate has nothing to enforce`);
  exit(1);
}
const exempt = new Set(npmrc.get('min-release-age-exclude') ?? []);
const registry = (npmrc.get('registry')?.[0] ?? 'https://registry.npmjs.org').replace(/\/+$/, '');

// Lockfile paths look like node_modules/a/node_modules/@scope/b; the installed
// package is whatever follows the *last* node_modules segment.
function nameFromPath(p) {
  const i = p.lastIndexOf('node_modules/');
  return i === -1 ? null : p.slice(i + 'node_modules/'.length);
}

const lock = JSON.parse(readFileSync(lockPath, 'utf8'));
if (lock.lockfileVersion < 2) {
  console.error(`::error::${lockPath} is lockfileVersion ${lock.lockfileVersion}; need >= 2 for resolved versions`);
  exit(1);
}

const wanted = new Map(); // name -> Set(version)
for (const [path, entry] of Object.entries(lock.packages ?? {})) {
  if (!path) continue;                       // the root project itself
  if (entry.link) continue;                  // workspace symlink, not a download
  const name = entry.name ?? nameFromPath(path);
  if (!name || !entry.version) continue;
  if (entry.resolved && !entry.resolved.startsWith(registry)) continue; // not from this registry
  if (!wanted.has(name)) wanted.set(name, new Set());
  wanted.get(name).add(entry.version);
}

if (wanted.size === 0) {
  console.error(`::error::${lockPath} yielded no registry packages to check — refusing to pass vacuously`);
  exit(1);
}

async function packumentTime(name, attempt = 0) {
  const url = `${registry}/${name.replace('/', '%2f')}`;
  try {
    const res = await fetch(url, { headers: { accept: 'application/json' } });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return (await res.json()).time ?? {};
  } catch (err) {
    if (attempt < 3) {
      await new Promise((r) => setTimeout(r, 400 * 2 ** attempt));
      return packumentTime(name, attempt + 1);
    }
    // A registry blip must not be reported as "everything is old enough".
    throw new Error(`${name}: ${err.message}`);
  }
}

const names = [...wanted.keys()];
const rows = [];
const failures = [];
let cursor = 0;

await Promise.all(
  Array.from({ length: Math.min(CONCURRENCY, names.length) }, async () => {
    while (cursor < names.length) {
      const name = names[cursor++];
      const time = await packumentTime(name);
      for (const version of wanted.get(name)) {
        const published = time[version];
        if (!published) {
          failures.push({ name, version, why: 'no publish date in registry' });
          continue;
        }
        const ageDays = (Date.now() - new Date(published).getTime()) / DAY;
        const row = { name, version, ageDays, exempt: exempt.has(name) };
        rows.push(row);
        if (ageDays < windowDays && !row.exempt) {
          failures.push({ name, version, why: `${ageDays.toFixed(1)}d old, needs ${windowDays}d` });
        }
      }
    }
  })
);

rows.sort((a, b) => a.ageDays - b.ageDays);
const fmt = (r) =>
  `  ${r.name}@${r.version}`.padEnd(52) +
  `${r.ageDays.toFixed(1)}d`.padStart(8) +
  (r.exempt ? '   exempt' : '');

console.log(`${rows.length} packages from ${names.length} names, window ${windowDays}d, registry ${registry}`);
console.log('youngest:');
rows.slice(0, 8).forEach((r) => console.log(fmt(r)));

if (exempt.size) {
  console.log(`\nexempt via min-release-age-exclude in ${npmrcPath}: ${[...exempt].join(', ')}`);
}

if (failures.length) {
  console.error(`\n::error::${failures.length} package(s) younger than the ${windowDays}-day window:`);
  for (const f of failures) console.error(`  ${f.name}@${f.version} — ${f.why}`);
  console.error(
    `\nIf one is a security fix that must land early, add its name to ` +
      `min-release-age-exclude in ${npmrcPath} with a comment saying why.`
  );
  exit(1);
}

console.log(`\nOK: nothing younger than ${windowDays} days.`);
